parameters.jsCode:
const DEFAULTS = {
  rev: 'personal-gtm-sprint1-unified',
  enabled: true,
  max_companies_per_run: 25,
  min_account_score: 65,
  priority_score: 80,
  allow_agencies: true,
  allow_startups: true,
  allow_smb: true,
  allow_enterprise: false,
  timezone: {
    allowed_utc_offsets: [0, 1, 2, 3, 4],
    allow_unknown_timezone: false
  },
  company: {
    employee_min: 2,
    employee_max: 150,
    must_have_domain: true,
    industries_include: [],
    industries_exclude: [],
    keywords_include: [],
    keywords_exclude: []
  },
  scoring: {
    weights: {
      icp_fit: 0.35,
      budget_proxy: 0.25,
      automation_need: 0.25,
      timezone_fit: 0.15
    },
    vertical_boost: {
      enabled: true,
      bonus: 5,
      keywords: []
    }
  }
};

const rows = $('Fetch Config').all().map(i => i.json);
const row = rows.find(r => String(r.key || '').trim().toLowerCase() === 'config_json');

let warnings = [];
let config = JSON.parse(JSON.stringify(DEFAULTS));

if (row && row.value) {
  try {
    const parsed = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;

    config = {
      ...config,
      ...parsed,
      timezone: {
        ...config.timezone,
        ...(parsed.timezone || {})
      },
      company: {
        ...config.company,
        ...(parsed.company || {})
      },
      scoring: {
        ...config.scoring,
        ...(parsed.scoring || {}),
        weights: {
          ...config.scoring.weights,
          ...((parsed.scoring || {}).weights || {})
        },
        vertical_boost: {
          ...config.scoring.vertical_boost,
          ...((parsed.scoring || {}).vertical_boost || {})
        }
      }
    };
  } catch (e) {
    warnings.push('config_json invalid: ' + String(e.message || e));
  }
} else {
  warnings.push('config_json missing; using defaults');
}

return [{ json: { config, warnings } }];

function normalizeDomain(raw) {
  if (!raw) return '';

  let value = String(raw).trim();

  try {
    if (!/^https?:\/\//i.test(value)) {
      value = 'https://' + value;
    }

    const u = new URL(value);
    return u.hostname.toLowerCase().replace(/^www\./, '');
  } catch (e) {
    return String(raw)
      .toLowerCase()
      .replace(/^https?:\/\//, '')
      .replace(/^www\./, '')
      .split('/')[0]
      .trim();
  }
}

const out = [];

for (const item of $input.all()) {
  const r = item.json;

  if (!r || r.__empty) continue;

  const company_name = String(r.company_name || '').trim();
  if (!company_name) continue;

  const domain = normalizeDomain(r.domain || r.website || '');
  const website = String(r.website || '').trim();

  const employeeRaw = String(r.employee_count || '').replace(/[^0-9]/g, '');
  const employeeNumber = Number(employeeRaw);
  const employee_count = Number.isFinite(employeeNumber) && employeeNumber > 0
    ? employeeNumber
    : null;

  const tzRaw = r.timezone_utc_offset;
  const tzNumber = Number(tzRaw);
  const timezone_utc_offset = tzRaw === undefined || tzRaw === null || String(tzRaw).trim() === ''
    ? null
    : (Number.isFinite(tzNumber) ? tzNumber : null);

  const description_text = [
    r.description,
    r.notes
  ]
    .filter(Boolean)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  out.push({
    json: {
      source: String(r.source || '').trim() || 'seed_accounts',   // S15: e.g. hubspot_directory
      company_name,
      domain,
      website,
      industry: String(r.industry || '').trim(),
      company_type: String(r.company_type || '').toLowerCase().trim(),
      employee_count,
      location_raw: String(r.location_raw || '').trim(),
      country: String(r.country || '').trim(),
      timezone_utc_offset,
      funding_stage: String(r.funding_stage || '').toLowerCase().trim(),
      description_text,
      status: String(r.status || 'new').toLowerCase().trim(),
      // S15 (ADR-113): blank or unknown means smb_direct
      lead_track: String(r.lead_track || '').trim().toLowerCase() === 'agency_partner' ? 'agency_partner' : 'smb_direct'
    }
  });
}

if (!out.length) {
  return [{ json: { __empty: true } }];
}

return out;

const { config, warnings } = $('Load Config').first().json;

const safeAll = (name) => {
  try { return $(name).all().map(i => i.json); } catch (e) { return []; }
};

const seenRows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.domain && String(r.domain).toLowerCase().trim() !== '__placeholder__');

const seenDomains = new Set(
  seenRows.map(r => String(r.domain).toLowerCase().trim())
);

// ---- Sprint 2: multi-source read ----
const mergedItems = safeAll('Merge Sources');
const markers = mergedItems.filter(a => a && (a.__error || a.__skipped));
const rawAccounts = mergedItems.filter(a => a && !a.__error && !a.__skipped && a.company_name);

const sourceCounts = {};
for (const a of rawAccounts) {
  const s = String(a.source || 'unknown');
  sourceCounts[s] = (sourceCounts[s] || 0) + 1;
}

const stats = {
  seed_rows: rawAccounts.length,
  seen_rows_pre: seenDomains.size,
  after_filters: 0,
  accounts_written: 0,
  below_min_score: 0,
  sources: sourceCounts,
  apollo_companies: sourceCounts.apollo || 0,
  source_errors: markers.map(m => m.__error || m.__skipped).slice(0, 8),
  rejected: {
    not_new: 0,
    no_domain: 0,
    seen: 0,
    duplicate_run: 0,
    employee_range: 0,
    company_type: 0,
    industry_include: 0,
    industry_exclude: 0,
    keyword_include: 0,
    keyword_exclude: 0,
    timezone: 0
  },
  errors: []
};

for (const m of markers) {
  if (m.__error) stats.errors.push(m.__error);
}

if (!config.enabled) {
  stats.errors.push('Workflow disabled by config.enabled=false');
  return [{
    json: {
      accounts: [],
      seen_rows: [],
      stats: {
        ...stats,
        warnings: (warnings || []).join(' | '),
        errors_sample: stats.errors.slice(0, 3).join(' | ')
      }
    }
  }];
}

const includesAny = (text, arr) => {
  const t = String(text || '').toLowerCase();
  return (arr || []).some(x => t.includes(String(x).toLowerCase()));
};


// ---- Sprint 15: lead tracks (ADR-113). agency_partner rows get their own filters and score; smb_direct is unchanged. ----
const AT = (config.lead_tracks || {}).agency_partner || {};
const trackOf = (a) => String(a.lead_track || '').trim().toLowerCase() === 'agency_partner' && AT.enabled !== false ? 'agency_partner' : 'smb_direct';
const metaOf = (a) => { try { const m = JSON.parse(a.source_meta || '{}'); return m && typeof m === 'object' ? m : {}; } catch (e) { return {}; } };
const lc = (arr) => (Array.isArray(arr) ? arr : []).map(x => String(x).toLowerCase());
const blankTz = (v) => v === null || v === undefined || v === '';
const agencyFilter = (a) => {
  const m = metaOf(a);
  const emp = a.employee_count;
  if (emp === null || emp === undefined || emp === '') { if (AT.allow_unknown_size === false) return 'agency_size'; }
  else if (Number(emp) > Number(AT.employee_max ?? 25)) return 'agency_size';
  if (lc(AT.exclude_tiers).includes((String(m.directory || '') + ':' + String(m.tier || '')).toLowerCase())) return 'agency_tier';
  if (lc(m.pricing).some(p => lc(AT.exclude_pricing).includes(p))) return 'agency_pricing';
  const langs = lc(m.languages);
  if (langs.length && lc(AT.required_languages).some(l => !langs.includes(l))) return 'agency_language';
  if (includesAny(a.industry, config.company.industries_exclude)) return 'industry_exclude';
  const text = [a.company_name, a.industry, a.description_text, a.location_raw].join(' ').toLowerCase();
  if (includesAny(text, config.company.keywords_exclude)) return 'keyword_exclude';
  if (!lc(AT.stack_keywords).some(k => text.includes(k))) return 'agency_stack_miss';
  const offsets = (AT.allowed_utc_offsets || (config.timezone || {}).allowed_utc_offsets || []).map(Number);
  if (blankTz(a.timezone_utc_offset)) { if (!(config.timezone || {}).allow_unknown_timezone) return 'timezone'; }
  else if (!offsets.includes(Number(a.timezone_utc_offset))) return 'timezone';
  return '';
};
// score = 0.35*stack_fit + 0.25*capacity_need + 0.20*size_fit + 0.20*tz_language_fit (plan 4.4)
const agencyScore = (a) => {
  const m = metaOf(a);
  const text = [a.company_name, a.industry, a.description_text].join(' ').toLowerCase();
  const kws = lc(AT.stack_keywords).filter(k => text.includes(k));
  const stack = kws.length >= 3 ? 100 : kws.length === 2 ? 75 : kws.length === 1 ? 50 : 0;
  let capacity = 40;
  if (Number(m.reviews || 0) >= 3) capacity += 20;
  if (/we'?re hiring|\bhiring\b|join our team|growing team|overflow|white[- ]label|subcontract|capacity/.test(text)) capacity += 20;
  if (m.availability === true) capacity += 20;
  capacity = Math.min(100, capacity);
  const tier = String(m.tier || '').toLowerCase();
  let size = ({ 'advanced artisan': 100, 'artisan': 100, 'select': 100, 'studio': 70, 'premium': 70 })[tier] ?? 60;
  if (lc(m.pricing).some(p => ['any-budget', '250-1000', '1000-5000'].includes(p))) size = Math.max(size, 90);
  const emp = Number(a.employee_count);
  if (a.employee_count !== null && a.employee_count !== '' && Number.isFinite(emp) && emp > 0) size = emp <= 10 ? 100 : (emp <= 25 ? Math.max(size, 80) : size);
  const off = blankTz(a.timezone_utc_offset) ? null : Number(a.timezone_utc_offset);
  let tzl = off === null ? 50 : [0, 1, 2].includes(off) ? 100 : [3, 4].includes(off) ? 80 : [-5, -4].includes(off) ? 60 : 30;
  if (lc(m.languages).length && !lc(m.languages).includes('english')) tzl = Math.min(tzl, 30);
  const final_score = Math.round(0.35 * stack + 0.25 * capacity + 0.20 * size + 0.20 * tzl);
  if (final_score < Number(AT.min_account_score ?? config.min_account_score ?? 60)) { stats.below_min_score++; return null; }
  return {
    run_date: new Date().toISOString(),
    source: a.source || 'partner_directory',
    account_id: 'acc_' + a.domain.replace(/[^a-z0-9]/gi, '_'),
    company_name: a.company_name,
    domain: a.domain,
    website: a.website || '',
    industry: a.industry || '',
    company_type: a.company_type || 'agency',
    employee_count: a.employee_count ?? '',
    location_raw: a.location_raw || '',
    country: a.country || '',
    timezone_utc_offset: a.timezone_utc_offset ?? '',
    funding_stage: a.funding_stage || '',
    final_score,
    priority: final_score >= Number(config.priority_score || 80),
    why_match: ['agency track', kws.length ? 'services: ' + kws.slice(0, 5).join(', ') : '', m.tier ? 'tier: ' + m.tier : '', m.directory ? 'directory: ' + m.directory : ''].filter(Boolean).join('; '),
    red_flags: [a.employee_count === null || a.employee_count === '' ? 'employee_count unknown' : '', off === null ? 'timezone unknown' : ''].filter(Boolean).join('; '),
    score_breakdown: `track=agency_partner; stack=${stack}; capacity=${capacity}; size=${size}; tz_lang=${tzl}`,
    confidence: 60,
    status: 'new',
    linkedin_url: a.linkedin_url || '',
    tech_stack: '',
    funding_proxy_score: size,
    automation_need_score: stack,
    enrichment_status: 'pending',
    lead_track: 'agency_partner',
    source_meta: a.source_meta || '',
    // ADR-117: the directory listing is the dated trigger for this track
    clay_trigger: a.directory_trigger || '',
    clay_trigger_source: a.directory_trigger ? 'directory' : '',
    clay_trigger_date: a.directory_trigger ? String(a.directory_trigger_date || new Date().toISOString().slice(0, 10)) : ''
  };
};

const currentRunDomains = new Set();
const filtered = [];

for (const a of rawAccounts) {
  if (a.status !== 'new') { stats.rejected.not_new++; continue; }

  if (config.company.must_have_domain && !a.domain) {
    stats.rejected.no_domain++;
    stats.errors.push(`Missing domain for ${a.company_name}`);
    continue;
  }

  if (seenDomains.has(a.domain)) { stats.rejected.seen++; continue; }
  if (currentRunDomains.has(a.domain)) { stats.rejected.duplicate_run++; continue; }

  // S15: agency_partner rows take the track filters (size, tier, pricing, language, stack, time window)
  if (trackOf(a) === 'agency_partner') {
    const why = agencyFilter(a);
    if (why) { stats.rejected[why] = (stats.rejected[why] || 0) + 1; continue; }
    currentRunDomains.add(a.domain);
    filtered.push(a);
    continue;
  }

  if (
    a.employee_count === null ||
    a.employee_count < Number(config.company.employee_min) ||
    a.employee_count > Number(config.company.employee_max)
  ) { stats.rejected.employee_range++; continue; }

  const type = String(a.company_type || '').toLowerCase();

  const typeAllowed =
    (type.includes('agency') && config.allow_agencies) ||
    (type.includes('startup') && config.allow_startups) ||
    (type.includes('smb') && config.allow_smb) ||
    (type.includes('enterprise') && config.allow_enterprise);

  if (!typeAllowed) { stats.rejected.company_type++; continue; }

  if (
    config.company.industries_include.length &&
    !includesAny(a.industry, config.company.industries_include)
  ) { stats.rejected.industry_include++; continue; }

  if (includesAny(a.industry, config.company.industries_exclude)) { stats.rejected.industry_exclude++; continue; }

  const search_text = [
    a.company_name,
    a.industry,
    a.description_text,
    a.funding_stage,
    a.location_raw
  ].join(' ').toLowerCase();

  if (
    config.company.keywords_include.length &&
    !includesAny(search_text, config.company.keywords_include)
  ) { stats.rejected.keyword_include++; continue; }

  if (includesAny(search_text, config.company.keywords_exclude)) { stats.rejected.keyword_exclude++; continue; }

  const tzConfig = config.timezone || {};
  const allowedOffsets = tzConfig.allowed_utc_offsets || [];

  if (a.timezone_utc_offset === null) {
    if (!tzConfig.allow_unknown_timezone) { stats.rejected.timezone++; continue; }
  } else if (!allowedOffsets.includes(a.timezone_utc_offset)) {
    stats.rejected.timezone++;
    continue;
  }

  currentRunDomains.add(a.domain);
  filtered.push(a);
}

stats.after_filters = filtered.length;

const weights = {
  icp_fit: 0.35,
  budget_proxy: 0.25,
  automation_need: 0.25,
  timezone_fit: 0.15,
  ...(config.scoring?.weights || {})
};

const vertical_boost = {
  enabled: false,
  bonus: 0,
  keywords: [],
  ...(config.scoring?.vertical_boost || {})
};

const scored = [];

for (const a of filtered) {
  if (trackOf(a) === 'agency_partner') { const row = agencyScore(a); if (row) scored.push({ json: row }); continue; }   // S15

  const search_text = [
    a.company_name,
    a.industry,
    a.description_text,
    a.funding_stage,
    a.location_raw
  ].join(' ').toLowerCase();

  const industryMatch = includesAny(a.industry, config.company.industries_include || []);

  const keywordMatches = (config.company.keywords_include || []).filter(k =>
    search_text.includes(String(k).toLowerCase())
  );

  const icp_fit = Math.min(
    100,
    (industryMatch ? 50 : 20) +
    Math.min(30, keywordMatches.length * 10) +
    (['startup', 'agency', 'smb'].includes(a.company_type) ? 20 : 0)
  );

  let budget_proxy = 0;

  if (['seed', 'pre_seed', 'series_a'].includes(a.funding_stage)) {
    budget_proxy += 30;
  } else if (a.funding_stage === 'bootstrapped') {
    budget_proxy += 15;
  }

  const emp = Number(a.employee_count) || 0;

  if (emp >= 5 && emp <= 100) budget_proxy += 30;
  else if (emp >= 2 && emp <= 4) budget_proxy += 15;
  else if (emp > 100 && emp <= 150) budget_proxy += 10;

  if (['startup', 'agency'].includes(a.company_type)) budget_proxy += 20;

  budget_proxy = Math.min(100, budget_proxy);

  const automationToolsMatch = includesAny(search_text, [
    'crm', 'hubspot', 'salesforce', 'clay', 'n8n', 'make.com', 'zapier'
  ]);

  const automation_need = Math.min(
    100,
    keywordMatches.length * 20 +
    (automationToolsMatch ? 25 : 0)
  );

  let timezone_fit = 0;

  if (a.timezone_utc_offset === null) {
    timezone_fit = config.timezone?.allow_unknown_timezone ? 30 : 0;
  } else if (a.timezone_utc_offset === 1) {
    timezone_fit = 100;
  } else if ([0, 2, 3].includes(a.timezone_utc_offset)) {
    timezone_fit = 90;
  } else if (a.timezone_utc_offset === 4) {
    timezone_fit = 75;
  } else {
    timezone_fit = 0;
  }

  let final_score = Math.round(
    weights.icp_fit * icp_fit +
    weights.budget_proxy * budget_proxy +
    weights.automation_need * automation_need +
    weights.timezone_fit * timezone_fit
  );

  if (vertical_boost.enabled && includesAny(search_text, vertical_boost.keywords || [])) {
    final_score = Math.min(100, final_score + Number(vertical_boost.bonus || 0));
  }

  if (final_score < Number(config.min_account_score || 0)) {
    stats.below_min_score++;
    continue;
  }

  const red_flags = [];
  if (a.employee_count === null) red_flags.push('employee_count unknown');
  if (a.timezone_utc_offset === null) red_flags.push('timezone unknown');
  if (a.funding_stage === 'unknown') red_flags.push('funding unknown');

  const why_match = [];
  if (industryMatch) why_match.push('industry fit');
  if (keywordMatches.length) why_match.push('keywords: ' + keywordMatches.slice(0, 5).join(', '));
  if (a.company_type) why_match.push('company type: ' + a.company_type);

  scored.push({
    json: {
      run_date: new Date().toISOString(),
      source: a.source || 'seed_accounts',
      account_id: 'acc_' + a.domain.replace(/[^a-z0-9]/gi, '_'),
      company_name: a.company_name,
      domain: a.domain,
      website: a.website || '',
      industry: a.industry || '',
      company_type: a.company_type || '',
      employee_count: a.employee_count ?? '',
      location_raw: a.location_raw || '',
      country: a.country || '',
      timezone_utc_offset: a.timezone_utc_offset ?? '',
      funding_stage: a.funding_stage || '',
      final_score,
      priority: final_score >= Number(config.priority_score || 80),
      why_match: why_match.join('; ') || 'seed match',
      red_flags: red_flags.join('; '),
      score_breakdown: `icp=${icp_fit}; budget=${budget_proxy}; automation=${automation_need}; timezone=${timezone_fit}`,
      confidence: a.source === 'apollo' ? 65 : 60,
      status: 'new',
      linkedin_url: a.linkedin_url || '',
      tech_stack: '',
      funding_proxy_score: budget_proxy, // Map existing proxy to new field
      automation_need_score: automation_need, // Map existing need to new field
      enrichment_status: 'pending',
      lead_track: 'smb_direct'   // S15 (ADR-113)
    }
  });
}

scored.sort((a, b) => b.json.final_score - a.json.final_score);

const capped = scored
  .slice(0, Number(config.max_companies_per_run || 25))
  .map(i => i.json);

stats.accounts_written = capped.length;

const seen_rows = capped.map(a => ({
  domain: a.domain,
  company_name: a.company_name,
  first_seen_at: new Date().toISOString(),
  last_seen_at: new Date().toISOString(),
  source: a.source || 'seed_accounts'
}));

stats.warnings = (warnings || []).join(' | ');
stats.errors_sample = stats.errors.slice(0, 3).join(' | ');

return [{
  json: {
    accounts: capped,
    seen_rows,
    stats
  }
}];

const pkg = $input.first().json;
const stats = pkg.stats || {};
const enr = stats.enrichment || {};
const clay = stats.clay || {};

let rev = 'unknown';
try { rev = ($('Load Config').first().json.config || {}).rev || 'unknown'; } catch (e) { /* keep unknown */ }
let minScore = 0;
try { minScore = Number(($('Load Config').first().json.config || {}).min_account_score || 0); } catch (e) { minScore = 0; }

const rejections = Object.entries(stats.rejected || {})
  .filter(([k, v]) => v > 0)
  .map(([k, v]) => `${k}:${v}`)
  .join(' | ');

// Sprint 14: outreach skip counters and needs_redraft go into rejection_summary as outreach_<key>:<n>.
const outreachCounters = Object.entries(stats.outreach || {})
  .filter(([k, v]) => (k.startsWith('skipped_') || k === 'needs_redraft') && typeof v === 'number' && v > 0)
  .map(([k, v]) => `outreach_${k}:${v}`)
  .join(' | ');

return [{
  json: {
    run_at: stats.run_at || new Date().toISOString(),
    config_rev: stats.config_rev || rev,
    source: Object.keys(stats.sources || {}).join('+') || 'seed_accounts',
    seed_rows: stats.seed_rows || 0,
    seen_rows_pre: stats.seen_rows_pre || 0,
    after_filters: stats.after_filters || 0,
    accounts_written: stats.accounts_written || 0,
    min_account_score: minScore,
    warnings: stats.warnings || '',
    errors_sample: stats.errors_sample || '',
    apollo_companies: stats.apollo_companies || 0,
    source_errors: (stats.source_errors || []).join(' | '),
    rejection_summary: [rejections, stats.below_min_score ? 'below_min_score:' + stats.below_min_score : '', outreachCounters].filter(Boolean).join(' | ') || 'none',
    enriched_rows: enr.rows || 0,
    enrich_errors: (enr.errors || []).join(' | '),
    clay_queued: clay.queued || 0,
    clay_merged: clay.merged || 0,
    contacts_discovered: (stats.contacts || {}).discovered || 0,
    contacts_written: (stats.contacts || {}).written || 0,
    outreach_drafts_written: (stats.outreach || {}).drafted || 0,
    llm_calls: (stats.outreach || {}).llm_calls || 0,
    llm_failures: (stats.outreach || {}).llm_failures || 0

  }
}];

const cfg = $('Load Config').first().json.config || {};
const A = (cfg.sources || {}).apollo || {};

if (A.enabled !== true) {
  return [{ json: { __skipped: 'apollo disabled by config' } }];
}

const KEY = $env.APOLLO_API_KEY;
if (!KEY) return [{ json: { __error: 'apollo: APOLLO_API_KEY missing from n8n env' } }];

const queries = (Array.isArray(A.queries) ? A.queries : []).filter(q => q && Array.isArray(q.keyword_tags) && q.keyword_tags.length);
if (!queries.length) return [{ json: { __error: 'apollo: no queries with keyword_tags in config' } }];

const URL_BASE = String(A.endpoint || 'https://api.apollo.io/api/v1/mixed_companies/search');
const cap = Math.max(1, Number(A.max_companies_per_run || 100));
const perPage = Math.max(1, Math.min(100, Number(A.per_page || 25)));
// Hard credit guard: Apollo bills 1 credit per page that returns results
const maxCalls = Math.max(1, Math.min(5, Number(A.max_credits_per_run || 3)));

const C = { calls: 0, orgs: 0, no_domain: 0, dup: 0, no_headcount: 0 };
const out = [];
const errors = [];
const seenDomains = new Set();

// Apollo documents these filters as query-string arrays: name[]=value
const enc = encodeURIComponent;
const arr = (name, values) => (values || []).map(v => enc(name + '[]') + '=' + enc(String(v))).join('&');

for (const q of queries) {
  if (out.length >= cap || C.calls >= maxCalls) break;

  const ranges = (Array.isArray(q.employee_ranges) && q.employee_ranges.length ? q.employee_ranges : ['11,50'])
    .map(r => String(r).replace(/-/g, ','));          // Apollo wants "11,50", never "11-50"
  const page = Math.max(1, Number(q.page || 1));
  const label = String(q.label || q.keyword_tags[0]);

  const qs = [
    arr('q_organization_keyword_tags', q.keyword_tags),
    arr('organization_num_employees_ranges', ranges),
    arr('organization_locations', q.locations || []),
    'page=' + page,
    'per_page=' + perPage
  ].filter(Boolean).join('&');

  let res = null;
  try {
    C.calls++;
    res = await this.helpers.httpRequest({
      method: 'POST',
      url: URL_BASE + '?' + qs,
      headers: { 'X-Api-Key': KEY, 'Content-Type': 'application/json', 'Accept': 'application/json', 'Cache-Control': 'no-cache' },
      body: {},
      json: true,
      timeout: 20000
    });
  } catch (e) {
    const status = (e.response && e.response.status) || e.httpCode || '';
    errors.push('apollo: ' + label + ' failed ' + status + ' ' + String(e.message || e).slice(0, 120));
    continue;
  }

  const orgs = [].concat(res.organizations || [], res.accounts || []);
  if (!orgs.length) { errors.push('apollo: ' + label + ' returned 0 results (page ' + page + ')'); continue; }
  C.orgs += orgs.length;

  // Lowest headcount in the query, used only if Apollo sends no number
  const floor = Math.min.apply(null, ranges.map(r => Number(String(r).split(',')[0]) || 1));

  for (const o of orgs) {
    if (out.length >= cap) break;
    const dom = String(o.primary_domain || o.domain || o.website_url || '').toLowerCase()
      .replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
    if (!dom) { C.no_domain++; continue; }
    if (seenDomains.has(dom)) { C.dup++; continue; }
    seenDomains.add(dom);
    if (!Number(o.estimated_num_employees)) C.no_headcount++;
    out.push({ json: Object.assign({}, o, {
      __domain: dom,
      __q: {
        label,
        keyword_tags: q.keyword_tags,
        industry_label: String(q.industry_label || ''),
        company_type: String(q.company_type || ''),
        first_location: String((q.locations || [])[0] || ''),
        headcount_floor: floor
      }
    }) });
  }
}

const note = 'apollo stats: credits_max=' + C.calls + ' orgs=' + C.orgs + ' no_domain=' + C.no_domain + ' dup=' + C.dup +
  ' no_headcount=' + C.no_headcount + ' returned=' + out.length;

const markers = errors.slice(0, 2).map(m => ({ json: { __error: m } }));
if (!out.length) return markers.length ? markers : [{ json: { __error: 'apollo: no results | ' + note } }];
return out.concat(markers, [{ json: { __skipped: note } }]);

// Deterministic country -> UTC offset map (no LLM, no paid geo API)
const COUNTRY_UTC = {
  'portugal': 0, 'ireland': 0, 'united kingdom': 0, 'uk': 0, 'iceland': 0,
  'germany': 1, 'france': 1, 'spain': 1, 'italy': 1, 'netherlands': 1, 'belgium': 1,
  'austria': 1, 'switzerland': 1, 'czech republic': 1, 'czechia': 1, 'poland': 1,
  'hungary': 1, 'slovakia': 1, 'slovenia': 1, 'croatia': 1, 'serbia': 1, 'malta': 1,
  'tunisia': 1, 'morocco': 1, 'algeria': 1, 'denmark': 1, 'norway': 1, 'sweden': 1,
  'luxembourg': 1,
  'greece': 2, 'romania': 2, 'bulgaria': 2, 'finland': 2, 'estonia': 2, 'latvia': 2,
  'lithuania': 2, 'ukraine': 2, 'cyprus': 2, 'israel': 2, 'lebanon': 2, 'egypt': 2,
  'turkey': 3, 'saudi arabia': 3, 'qatar': 3, 'kuwait': 3, 'bahrain': 3, 'iraq': 3, 'jordan': 3,
  'united arab emirates': 4, 'uae': 4, 'georgia': 4, 'armenia': 4, 'azerbaijan': 4
};
const tzFor = (name) => {
  const k = String(name || '').toLowerCase().trim();
  return COUNTRY_UTC[k] !== undefined ? COUNTRY_UTC[k] : null;
};

const out = [];

for (const item of $input.all()) {
  const r = item.json;

  // Pass failure/skip markers through for telemetry
  if (r.__error || r.__skipped) { out.push({ json: r }); continue; }

  const q = r.__q || {};
  const domain = String(r.__domain || r.primary_domain || r.domain || '').toLowerCase().trim();
  if (!domain) continue;

  // Headcount: Apollo's number, else the lowest size the query asked for
  const empRaw = Number(r.estimated_num_employees || r.employee_count || 0);
  const fromQuery = !(Number.isFinite(empRaw) && empRaw > 0);
  const employee_count = fromQuery ? (Number(q.headcount_floor) || null) : empRaw;

  const keywords = Array.isArray(r.keywords) ? r.keywords : [];
  const text = [r.industry, r.name, r.short_description, keywords.join(' ')].join(' ').toLowerCase();

  // Company type: the query's label wins, the old heuristic is the fallback
  let company_type = String(q.company_type || '').toLowerCase();
  if (!company_type) {
    if (text.includes('agency')) company_type = 'agency';
    else if (Number(r.founded_year || 0) >= 2015) company_type = 'startup';
    else if (employee_count !== null && employee_count <= 150) company_type = 'smb';
    else company_type = 'enterprise';
  }

  // Timezone: Apollo's country, else the first location the query filtered on
  const country = String(r.country || '').trim();
  let timezone_utc_offset = tzFor(country);
  if (timezone_utc_offset === null) timezone_utc_offset = tzFor(q.first_location);

  out.push({
    json: {
      source: 'apollo',
      company_name: String(r.name || domain).trim(),
      domain,
      website: String(r.website_url || r.website || ('https://' + domain)),
      // Apollo industry names ("marketing & advertising") do not match your include list, so the query label leads
      industry: [q.industry_label, r.industry].filter(Boolean).join(' | ').toLowerCase() || 'unknown',
      company_type,
      employee_count,
      location_raw: [r.city, r.state, r.country].filter(Boolean).join(', ') || String(q.first_location || ''),
      country: country || String(q.first_location || ''),
      timezone_utc_offset,
      funding_stage: String(r.latest_funding_stage || r.funding_stage || 'unknown').toLowerCase().replace(/\s+/g, '_'),
      description_text: [
        r.short_description || '',
        keywords.slice(0, 15).join(' '),
        Array.isArray(r.technology_names) ? r.technology_names.slice(0, 10).join(' ') : '',
        'Apollo keyword tags matched: ' + (q.keyword_tags || []).join(', ') + '.',
        fromQuery ? 'Headcount is the query minimum, not a measured value.' : ''
      ].join(' ').replace(/\s+/g, ' ').trim().slice(0, 2500),
      status: 'new',
      apollo_id: String(r.id || ''),
      linkedin_url: String(r.linkedin_url || '')
    }
  });
}

return out;

const cfg = $('Load Config').first().json.config || {};
const A = (cfg.sources || {}).hn_hiring || {};

if (A.enabled !== true) {
  return [{ json: { __skipped: 'hn_hiring disabled by config' } }];
}

const keywords = (cfg.company?.keywords_include || []).map(k => String(k).toLowerCase());
const cap = Math.max(1, Number(A.max_companies_per_run || 400));
const threadsWanted = Math.max(1, Math.min(4, Number(A.threads || 2)));
// Signal gate: a post must mention at least one GTM-specific keyword, not only a generic one like "b2b"
const strong = (Array.isArray(A.strong_keywords) ? A.strong_keywords : []).map(k => String(k).toLowerCase());

// Per-gate counters: telemetry first, never a blind rewrite again
const C = { threads: 0, top_level: 0, keyword_hits: 0, weak_drop: 0, url_fail: 0, dup_drop: 0, tz_null: 0 };

const NOISE_HOSTS = [
  'workable.com','greenhouse.io','lever.co','ashbyhq.com','smartrecruiters.com',
  'indeed.com','glassdoor.com','linkedin.com','github.com','twitter.com','x.com',
  'medium.com','wikipedia.org','youtube.com','docs.google.com','forms.gle',
  'news.ycombinator.com','hn.algolia.com',
  // personal sites, site builders and job boards are not companies
  'vercel.app','netlify.app','github.io','notion.site','notion.so','webflow.io','carrd.co',
  'substack.com','calendly.com','typeform.com','google.com','bit.ly','t.co','linktr.ee',
  'nordictechjobs.com','mycreportfolio.com','wellfound.com','angel.co','ycombinator.com',
  'workatastartup.com','breezy.hr','recruitee.com','teamtailor.com','bamboohr.com','personio.de',
  'personio.com','rippling.com','gem.com','jobvite.com','icims.com','myworkdayjobs.com','notion.com'
].concat((Array.isArray(A.extra_noise_hosts) ? A.extra_noise_hosts : []).map(h => String(h).toLowerCase()));
const ATS_PREFIXES = ['ats.', 'jobs.', 'careers.', 'apply.', 'boards.', 'hire.', 'recruiting.'];

const HOST_RE = /https?:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}/i;
const URL_RE  = /https?:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}(?:\/[^\s<>"']*)?/gi;

// whole-word match, so "clay" does not match "barclays"
const hasWord = (text, k) => new RegExp('(^|[^a-z0-9])' + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(text);

const isNoise = (host) => NOISE_HOSTS.some(n => host === n || host.endsWith('.' + n));

function cleanHost(host) {
  host = host.replace(/^https?:\/\//i, '').toLowerCase().replace(/^www\./, '');
  for (const prefix of ATS_PREFIXES) {
    if (host.startsWith(prefix)) host = host.substring(prefix.length);
  }
  return host;
}

function pickDomain(text) {
  const urls = String(text).match(URL_RE) || [];
  for (const u of urls) {
    const m = u.match(HOST_RE);
    if (!m) continue;
    const host = cleanHost(m[0]);
    if (isNoise(host)) continue;
    return { domain: host, url: u.replace(/[.,;:)\]]+$/, '') };
  }
  return null;
}

function parseTz(t) {
  if (/utc\+2|eastern europe|athens|bucharest|cairo|kyiv|kiev|tallinn|estonia|helsinki|finland|latvia|vilnius|romania|bulgaria|greece/i.test(t)) return 2;
  if (/utc\+1|cet\b|cest\b|central europe|berlin|paris|madrid|rome|amsterdam|tunis|munich|barcelona|warsaw|prague|vienna|stockholm|oslo|copenhagen|sweden|norway|denmark|poland|germany|france|spain|italy|netherlands|belgium|austria|switzerland/i.test(t)) return 1;
  if (/utc\+0|\bgmt\b|\buk\b|london|dublin|lisbon|ireland|england|scotland/i.test(t)) return 0;
  if (/utc\+3|moscow|istanbul|riyadh|nairobi|doha|bahrain|kuwait|saudi|turkey|israel|tel aviv/i.test(t)) return 3;
  if (/utc\+4|dubai|\buae\b|baku|tbilisi|yerevan|georgia|armenia|azerbaijan/i.test(t)) return 4;
  if (/remote[^\n]{0,40}(europe|emea|\beu\b)|(europe|emea)[^\n]{0,40}remote|european hours|\beu hours/i.test(t)) return 1;
  if (/\best\b|\bedt\b|eastern time|new york|toronto|central time|chicago|pacific time|los angeles|seattle|united states|\bus only|\busa\b|\bus\b|americas/i.test(t)) return -5;
  return null;
}

function parseFunding(t) {
  if (/series\s*a/i.test(t)) return 'series_a';
  if (/series\s*b/i.test(t)) return 'series_b';
  if (/series\s*[c-f]\b/i.test(t)) return 'series_c';
  if (/pre-?seed|\bseed\b/i.test(t)) return 'seed';
  if (/bootstrapped|profitable|self-funded/i.test(t)) return 'bootstrapped';
  return 'unknown';
}

function parseHeadcount(t) {
  const m = t.match(/(?:we(?:'re| are)?|team of|currently|now)\s+(\d{1,4})\s+(?:people|employees|engineers|folks)/i)
         || t.match(/(\d{1,4})\s+(?:people|employees)\b/i);
  const n = m ? Number(m[1]) : NaN;
  return Number.isFinite(n) && n > 0 && n <= 10000 ? n : 15;
}

// Returns the top-level comments (= company posts) of one thread
async function loadTopLevel(storyId) {
  let top = [];
  try {
    const thread = await this.helpers.httpRequest({ method: 'GET', json: true, url: 'https://hn.algolia.com/api/v1/items/' + storyId });
    top = (thread.children || []).filter(c => c && c.text).map(c => ({ text: c.text }));
  } catch (e) { top = []; }
  if (!top.length) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', json: true,
        url: 'https://hn.algolia.com/api/v1/search?tags=comment,story_' + storyId + '&hitsPerPage=1000'
      });
      top = (res.hits || [])
        .filter(h => h && String(h.parent_id) === storyId && (h.comment_text || h.text))
        .map(h => ({ text: h.comment_text || h.text }));
    } catch (e) { top = []; }
  }
  return top;
}

try {
  // Newest "Who is hiring" threads from the last ~75 days (usually 2 or 3 monthly threads)
  const since = Math.floor(Date.now() / 1000) - 75 * 24 * 3600;
  const search = await this.helpers.httpRequest({
    method: 'GET', json: true,
    url: 'https://hn.algolia.com/api/v1/search_by_date?tags=story&query=' + encodeURIComponent('Ask HN: Who is hiring') +
         '&numericFilters=created_at_i%3E' + since + '&hitsPerPage=20'
  });

  const stories = (search.hits || [])
    .filter(h => /^ask hn: who is hiring/i.test(h.title || '') && /\([a-z]+ \d{4}\)/i.test(h.title || ''))
    .sort((a, b) => b.created_at_i - a.created_at_i)
    .slice(0, threadsWanted);

  if (!stories.length) return [{ json: { __error: 'hn_hiring: no monthly thread found', __counters: C } }];
  C.threads = stories.length;

  const out = [];
  const seenDomains = new Set();

  for (const story of stories) {
    const storyId = String(story.objectID);
    const topLevel = await loadTopLevel.call(this, storyId);
    C.top_level += topLevel.length;

    for (const c of topLevel) {
      if (out.length >= cap) break;
      const clean = String(c.text)
        .replace(/<[^>]*>/g, ' ')
        .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&#x27;/g, "'").replace(/&quot;/g, '"').replace(/&#x2F;/g, '/')
        .replace(/\s+/g, ' ').trim();
      const lower = clean.toLowerCase();

      if (keywords.length && !keywords.some(k => lower.includes(k))) continue;
      C.keyword_hits++;
      if (strong.length && !strong.some(k => hasWord(lower, k))) { C.weak_drop++; continue; }

      let picked = null;
      const hrefM = String(c.text).match(/href=["']([^"']+)["']/i);
      if (hrefM) {
        const hm = hrefM[1].match(HOST_RE);
        const host = hm ? cleanHost(hm[0]) : '';
        if (host && !isNoise(host)) picked = { domain: host, url: hrefM[1] };
      }
      if (!picked) picked = pickDomain(clean);
      if (!picked) { C.url_fail++; continue; }
      if (seenDomains.has(picked.domain)) { C.dup_drop++; continue; }
      seenDomains.add(picked.domain);

      const tz = parseTz(lower);
      if (tz === null) C.tz_null++;

      out.push({
        json: {
          source: 'hn_hiring',
          company_name: picked.domain,
          domain: picked.domain,
          website: picked.url,
          industry: 'software',
          company_type: 'startup',
          employee_count: parseHeadcount(lower),
          location_raw: 'Remote',
          country: '',
          timezone_utc_offset: tz,
          funding_stage: parseFunding(lower),
          description_text: clean.slice(0, 2500),   // was 1000: keeps this gate and Process Accounts consistent
          status: 'new',
          hn_thread: storyId
        }
      });
    }
  }

  const note = 'hn stats: threads=' + C.threads + ' top_level=' + C.top_level + ' keyword_hits=' + C.keyword_hits + ' weak=' + C.weak_drop +
               ' url_fail=' + C.url_fail + ' dup=' + C.dup_drop + ' tz_null=' + C.tz_null + ' returned=' + out.length;

  if (!out.length) return [{ json: { __error: 'hn_hiring: 0 companies after gates | ' + note, __counters: C } }];
  return out.concat([{ json: { __skipped: note } }]);

} catch (e) {
  return [{ json: { __error: 'hn_hiring: ' + String(e.message || e).slice(0, 200), __counters: C } }];
}

const safeAll = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const cfg = $('Load Config').first().json.config || {};
const C = cfg.clay || {};
// Enrich Companies first: its rows are fresher than the sheet read, and the stats item rides along
const items = [...safeAll('Fetch Accounts For Clay'), ...safeAll('Add Enrich Stats')];
const statsItem = items.find(r => r && r.__row_type === 'stats');
const accountRows = items.filter(r => r && r.account_id && r.domain);

const base = statsItem ? JSON.parse(JSON.stringify(statsItem)) : { __row_type: 'stats', stats: {} };
base.stats = base.stats || {};

if (C.enabled === false) {
  base.stats.clay = { queued: 0, merged: 0, skipped: 'clay disabled by config' };
  return [{ json: base }];
}

const minScore = Number(C.min_score_for_clay || 65);
const cap = Math.max(1, Number(C.max_rows_per_run || 10));

// Only website-verified, never-queued, score-qualified accounts burn Clay credits
const seenIds = new Set();
const uniqueAccounts = accountRows.filter(r => {
  if (seenIds.has(r.account_id)) return false;
  seenIds.add(r.account_id);
  return true;
});
const eligible = uniqueAccounts.filter(r =>
  String(r.status || '') !== 'rejected' &&
  String(r.clay_status || '').trim() === '' &&
  String(r.enrichment_status || '') === 'enriched' &&
  Number(r.final_score || 0) >= minScore &&
  // S15 (ADR-118): the directory profile already gives services, tier and languages
  !(String(r.lead_track || '') === 'agency_partner' && ((cfg.lead_tracks || {}).agency_partner || {}).clay_research === false)
);

const queued = eligible.slice(0, cap).map(r => ({
  json: {
    queued_at: new Date().toISOString(),
    account_id: r.account_id,
    domain: r.domain,
    company_name: r.company_name,
    website: r.website,
    linkedin_url: r.linkedin_url || '',
    final_score: r.final_score,
    tech_stack_n8n: r.tech_stack || '',
    clay_status: 'queued'
  }
}));

base.stats.all_accounts = uniqueAccounts;

base.stats.clay = {
  queued: queued.length,
  merged: 0,
  eligible: eligible.length,
  skipped_over_cap: Math.max(0, eligible.length - cap)
};
return queued.concat([{ json: base }]);

const safeAll = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
// Input is Select Clay Batch (carries the stats item). Sheet data is read by name.
const items = [...$input.all().map(i => i.json), ...safeAll('Fetch Accounts For Clay'), ...safeAll('Fetch Clay Results')];
const statsItem = items.find(r => r && r.__row_type === 'stats');
const directAccounts = items.filter(r => r && r.account_id && r.domain && r.enrichment_status !== undefined);
const accountRows = directAccounts.length ? directAccounts : ((statsItem && statsItem.stats && Array.isArray(statsItem.stats.all_accounts)) ? statsItem.stats.all_accounts : []);

const clayMap = {};
for (const r of items) {
  if (!r || r.__row_type || r.account_id) continue;
  const d = String(r.domain || '').toLowerCase().trim();
  if (!d || d === '__placeholder__') continue;
  clayMap[d] = r;
}

const base = statsItem ? JSON.parse(JSON.stringify(statsItem)) : { __row_type: 'stats', stats: {} };
base.stats = base.stats || {};
base.stats.clay = base.stats.clay || { queued: 0 };

const STAGES = ['pre_seed', 'seed', 'series_a', 'series_b', 'bootstrapped'];
const updated = [];
let merged = 0;

for (const a of accountRows) {
    if (String(a.clay_status || '') === 'clay_done') continue;
  const c = clayMap[String(a.domain || '').toLowerCase().trim()];
  if (!c) continue;
  const row = Object.assign({}, a);

  // 1. LinkedIn: blank-fill only (never overwrite verified data)
  if (!String(row.linkedin_url || '').trim() && String(c.linkedin_url || '').trim()) {
    row.linkedin_url = String(c.linkedin_url).trim();
  }

  // 2. Headcount: Clay wins only over heuristic placeholders (empty or 15)
  const ce = Number(String(c.employee_count_clay || '').replace(/[^0-9]/g, ''));
  const cur = Number(row.employee_count || 0);
  if (Number.isFinite(ce) && ce > 0 && (cur === 0 || cur === 15)) row.employee_count = ce;

  // 3. Tech stack: union of n8n regex stack + Clay stack
const clayStack = String(c.tech_stack_clay || '').split(',').map(s => s.trim().toLowerCase()).filter(s => s && s !== 'none');
  const n8nStack = String(row.tech_stack || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  const union = Array.from(new Set(n8nStack.concat(clayStack)));
  const added = union.length - n8nStack.length;
  if (added > 0) row.tech_stack = union.join(', ');

  // 4. Funding: upgrade only from 'unknown'
  const cs = String(c.funding_stage_clay || '').toLowerCase().trim();
  let upgraded = false;
  if (String(row.funding_stage || '') === 'unknown' && STAGES.includes(cs)) {
    row.funding_stage = cs;
    upgraded = true;
  }
  if (upgraded) {
    row.red_flags = String(row.red_flags || '').split('; ').filter(f => f && f !== 'funding unknown').join('; ');
    row.funding_proxy_score = Math.min(100, Number(row.funding_proxy_score || 0) + 30);
  } else if (added > 0) {
    row.funding_proxy_score = Math.min(100, Number(row.funding_proxy_score || 0) + 10);
  }

  // 5. Evidence columns
  row.clay_summary = String(c.claygent_summary || '').slice(0, 500);
  row.clay_status = 'clay_done';
  row.clay_enriched_at = new Date().toISOString();
  row.confidence = Math.min(90, Number(row.confidence || 60) + 5);

  updated.push({ json: row });
  merged++;
}

base.stats.clay.merged = merged;
return updated.concat([{ json: base }]);

const safeAll = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const cfg = $('Load Config').first().json.config || {};
const K = cfg.contact || {};
const CC = cfg.clay_contacts || {};
// Sprint 14: EU and UK accounts get contacts first. Same list and config as Select Outreach Pairs.
