  const facts = (String(p.clay_summary || '') + ' ' + String(p.__site || '') + ' ' + p.employee_count + ' ' + o.proof_point + ' ' + ctaFor(p) + ' ' + p.tech_stack + ' ' + String(p.clay_trigger || '') + (isAgency(p) ? ' ' + String(p.source_meta || '') : '')).toLowerCase();
  const nums = (lower.replace(/\b[a-z]+\d[a-z0-9]*\b/g, ' ').match(/\d+/g) || []).filter(n => !facts.includes(n));
  if (nums.length) bad.push('invented_numbers:' + nums.join(','));
