  const paras = o.message_draft.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean).slice(1, -1);   // skip "Hi X," and the sender
  if (paras.some(s => !/[.!?]["')]?$/.test(s))) bad.push('unpunctuated_end');
  const words = s => String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  const src = ' ' + words(String(p.clay_summary || '') + ' ' + String(p.__site || '')).join(' ') + ' ';
  const mw = words(o.message_draft);
  for (let i = 0; i + 12 <= mw.length; i++) if (src.includes(' ' + mw.slice(i, i + 12).join(' ') + ' ')) { bad.push('copied_source'); break; }
  // Sprint 15: validator v3, agency rules (plan 4.8): one of their services, one small first task, no seniority claims.
  if (isAgency(p)) {
    const svc = agencyServiceWords(p);
    // their service must be named outside my own proof sentence ("I built ... HubSpot sync" does not count)
    const core = (o.first_line + ' ' + o.body_rest.split(/(?<=[.!?])\s+/).filter(x => !/\b(i|we)('ve| have)? built\b|relevant proof/i.test(x)).join(' ')).toLowerCase();
    if (svc.length && !svc.some(w => has(core, w))) bad.push('agency_no_service');
    if (!/\b(one|a|single)\s+(?:[a-z-]+\s+){0,2}(task|build|piece|project|job)\b/i.test(o.body_rest + ' ' + o.value_proposition) ||
        !/\b(small|scoped|fixed[- ]scope|first|trial|single)\b/i.test(o.body_rest + ' ' + o.value_proposition)) bad.push('agency_no_small_task');
    if (SENIOR.test(all)) bad.push('seniority_claim');
  }
  return bad;
};

const proofSentence = t => (/^can /i.test(t) ? 'I ' + t.replace(/^./, c => c.toLowerCase()) : /^built /i.test(t) ? 'I ' + t.replace(/^./, c => c.toLowerCase()) : t) + '.';
const templateDraft = p => {
  const cap = t => t.replace(/\b\w/g, c => c.toUpperCase());
